const loggedMissing = new Set<string>();

export function getHeadshotUrl(playerId: string, playerName?: string): string | undefined {
  const url = PLAYER_HEADSHOTS[playerId];
  if (!url) return undefined;
  return resolveHeadshotUrl(url);
}

/** Prefer full-resolution ESPN headshots; upgrade combiner/thumbnail paths when present. */
export function resolveHeadshotUrl(url: string): string {
  if (url.includes('/headshots/nba/players/full/')) return url;
  const fullMatch = url.match(/\/players\/full\/(\d+)\./);
  if (fullMatch) {
    return `https://a.espncdn.com/i/headshots/nba/players/full/${fullMatch[1]}.png`;
  }
  return url;
}

export function logMissingHeadshot(playerId: string, playerName: string): void {
  if (PLAYER_HEADSHOTS[playerId] || loggedMissing.has(playerId)) return;
  loggedMissing.add(playerId);
  console.warn(`[Trade Up] Missing ESPN headshot for ${playerName} (${playerId}) — using initials fallback.`);
}
